package com.umc.pediupatrao.controller;
import com.umc.pediupatrao.entity.Pedido; import com.umc.pediupatrao.service.PedidoService; import org.springframework.web.bind.annotation.*; import java.util.List; import java.math.BigDecimal; import java.util.Map;
@RestController @RequestMapping("/api/pedidos") public class PedidoController {private final PedidoService service;public PedidoController(PedidoService s){service=s;} @PostMapping public Pedido criarPedido(@RequestBody Pedido pedido){return service.criarPedido(pedido);} @GetMapping public List<Pedido> listarPedidos(){return service.listarPedidos();} @PutMapping("/{id}/status") public Pedido atualizarStatus(@PathVariable String id,@RequestParam String status){return service.atualizarStatus(id,status);} @PostMapping("/{id}/desconto") public Pedido desconto(@PathVariable String id,@RequestBody Map<String,BigDecimal> body){return service.aplicarDesconto(id,body.get("percentual"));} @PostMapping("/{id}/cancelar") public Pedido cancelar(@PathVariable String id,@RequestBody Map<String,String> body){return service.cancelar(id,body.get("justificativa"));}}
